    [9, 9, 6, 6, 6, 9, 9, 9, 9, 9, 9, 9, 9, 1, 1, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 5, 5, 9, 1, 1, 9, 2, 2, 2, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 9, 5, 5, 5, 9, 9, 1, 9, 2, 2, 2, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 5, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 4, 4, 4, 6, 9, 9, 5, 9, 5, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 4, 4, 4, 4, 9, 9, 9, 5, 9, 5, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9]
]

from collections import defaultdict, deque

# Build adjacency
h, w = 19, 22
all_pixels = defaultdict(set)
for r in range(h):
    for c in range(w):
        col = grid[r][c]
        all_pixels[col].add((r, c))

adj_set = set()
for col in all_pixels:
    for r, c in all_pixels[col]:
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            r2, c2 = r+dr, c+dc
            if 0 <= r2 < h and 0 <= c2 < w:
                col2 = grid[r2][c2]
                if col2 in all_pixels and col2 != col:
                    if col < col2:
                        adj_set.add((col, col2))
                    else:
                        adj_set.add((col2, col))
adj = defaultdict(set)
for c1, c2 in adj_set:
    adj[c1].add(c2)
    adj[c2].add(c1)

# Find connected components
visited = set()
components = []
for c in all_pixels:
    if c not in visited:
        comp = set()
        queue = deque([c])
        while queue:
            node = queue.popleft()
            if node in visited:
                continue
            visited.add(node)
            comp.add(node)
            for nb in adj[node]:
                if nb not in visited:
                    queue.append(nb)
        components.append(comp)

print("Shape components:", components)

# From my earlier analysis, only {4,6} are adjacent. Let me check if that's still the case
# Actually wait, I'm checking shape adjacency - but maybe I should think about something else

# What if I need to look at this differently?
# Let me check if there's a "dominant" or "largest" connected structure

# Let me print all shape sizes and which component they're in
for comp in components:
    for c in comp:
        print(f"Color {c}: size={len(all_pixels[c])}")

# Keep only component of size > 1 (i.e., only {4,6})
connected_only = {c for c in all_pixels for comp in components if c in comp and len(comp) > 1}
print(f"\nKept colors (connected): {sorted(connected_only)}")

# Create output grid
if connected_only:
    filtered = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] in connected_only:
                filtered[r][c] = 1
            else:
                filtered[r][c] = 9
    print("\nFiltered grid:")
    for row in filtered:
        print(*row)

    action = {"action": "submit", "grid": filtered}
    import json
    print(json.dumps(action))
else:
    # If no connected shapes, submit empty
    action = {"action": "submit", "grid": [[9]*w for _ in range(h)]}

